import { useState } from 'react';
import { BadgeCheck, Building2, Eye, EyeOff, FileCheck2, LockKeyhole, Monitor, ShieldCheck, Upload } from 'lucide-react';
import { PageHeading, Status } from './VendorUi';

function SettingsForm({ type, values, onSave }) {
  const [draft, setDraft] = useState(values);
  const business = type === 'business';
  const fields = business ? [['name', 'Nama bisnis'], ['email', 'Email bisnis', 'email'], ['phone', 'Nomor WhatsApp', 'tel'], ['city', 'Kota operasional'], ['address', 'Alamat bisnis'], ['description', 'Tentang bisnis', 'textarea']] : [['name', 'Nama lengkap'], ['email', 'Email', 'email'], ['phone', 'Nomor WhatsApp', 'tel'], ['organization', 'Organisasi (opsional)']];
  return <form className="v-card v-settings-form" onSubmit={event => { event.preventDefault(); onSave(type, draft); }}><div className="v-section-heading"><div className="v-heading-icon">{business ? <Building2 size={20} /> : <BadgeCheck size={20} />}</div><div><h2>{business ? 'Informasi bisnis' : 'Data pribadi & kontak'}</h2><p>{business ? 'Informasi yang membantu pelanggan mengenal bisnis Anda.' : 'Kelola informasi pemilik dan kontak operasional.'}</p></div></div><div className="v-form-grid">{fields.map(([key, label, fieldType = 'text']) => <div className={`v-field${fieldType === 'textarea' || key === 'address' ? ' v-field-wide' : ''}`} key={key}><label htmlFor={`settings-${key}`}>{label}</label>{fieldType === 'textarea' ? <textarea id={`settings-${key}`} rows={4} value={draft[key]} onChange={event => setDraft(current => ({ ...current, [key]: event.target.value }))} /> : <input id={`settings-${key}`} type={fieldType} value={draft[key]} required={key !== 'organization'} onChange={event => setDraft(current => ({ ...current, [key]: event.target.value }))} />}</div>)}</div><div className="v-form-actions"><button className="v-button v-button-secondary" type="button" onClick={() => setDraft(values)}>Batalkan perubahan</button><button className="v-button v-button-primary" type="submit">Simpan perubahan</button></div></form>;
}

function Security({ notify }) {
  const [visible, setVisible] = useState(false);
  const [twoFactor, setTwoFactor] = useState(false);
  const [error, setError] = useState('');
  return <><PageHeading title="Keamanan akun" description="Kelola kata sandi dan preferensi keamanan workspace." /><div className="v-settings-grid"><form className="v-card v-settings-form" onSubmit={event => {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    if (String(form.get('newPassword')).length < 8) { setError('Kata sandi baru minimal 8 karakter.'); return; }
    if (form.get('newPassword') !== form.get('confirmation')) { setError('Konfirmasi kata sandi belum sama.'); return; }
    setError(''); event.currentTarget.reset(); notify('Pratinjau perubahan kata sandi selesai. Kata sandi akun tidak diubah.');
  }}><div className="v-section-heading"><h2>Ubah kata sandi</h2><button className="v-icon-button" type="button" aria-label={visible ? 'Sembunyikan kata sandi' : 'Tampilkan kata sandi'} onClick={() => setVisible(value => !value)}>{visible ? <EyeOff size={18} /> : <Eye size={18} />}</button></div><div className="v-form-stack">{[['currentPassword', 'Kata sandi saat ini'], ['newPassword', 'Kata sandi baru'], ['confirmation', 'Konfirmasi kata sandi baru']].map(([key, label]) => <div className="v-field" key={key}><label htmlFor={key}>{label}</label><input id={key} name={key} type={visible ? 'text' : 'password'} required autoComplete={key === 'currentPassword' ? 'current-password' : 'new-password'} aria-describedby={key === 'newPassword' ? 'v-password-hint' : undefined} /></div>)}<p className="v-field-hint" id="v-password-hint">Gunakan minimal 8 karakter.</p>{error && <p className="v-field-error" role="alert">{error}</p>}</div><div className="v-form-actions"><button type="submit" className="v-button v-button-primary">Perbarui kata sandi</button></div></form><div className="v-form-stack"><section className="v-card v-security-card"><div className="v-heading-icon"><ShieldCheck size={22} /></div><h2>Autentikasi dua langkah</h2><p>Tambahkan lapisan keamanan saat masuk dari perangkat baru.</p><div className="v-toggle-row"><div><strong>Verifikasi tambahan</strong><small>{twoFactor ? 'Aktif pada pratinjau' : 'Belum diaktifkan pada pratinjau'}</small></div><button type="button" className="v-switch" role="switch" aria-checked={twoFactor} aria-label="Autentikasi dua langkah pada pratinjau" onClick={() => { setTwoFactor(value => !value); notify('Preferensi keamanan diubah pada pratinjau frontend.'); }}><span /></button></div></section><section className="v-card v-security-card"><div className="v-section-heading"><h2>Perangkat contoh</h2><Monitor size={18} /></div><div className="v-device"><span className="v-device-icon"><LockKeyhole size={19} /></span><div><strong>Chrome di Windows</strong><small>Contoh tampilan sesi perangkat</small></div></div></section></div></div></>;
}

function Kyc({ notify }) {
  const [files, setFiles] = useState({});
  return <><PageHeading title="Verifikasi identitas" description="Informasi verifikasi pemilik dan legalitas bisnis vendor." /><section className="v-card v-kyc-summary"><div className="v-kyc-icon"><ShieldCheck size={30} strokeWidth={1.4} /></div><div><Status>Terverifikasi</Status><h2>Identitas bisnis telah diverifikasi</h2><p>Status contoh untuk menampilkan halaman KYC vendor.</p></div><span className="v-date-pill">18 November 2026</span></section><div className="v-settings-grid"><section className="v-card v-detail-card"><div className="v-section-heading"><h2>Data verifikasi</h2><BadgeCheck size={19} /></div><dl>{[['Nama pemilik', 'Bagas Arya Pratama'], ['Nama bisnis', 'Roder Bogor Tenda Megah'], ['Nomor identitas', '3271 •••• •••• 0001'], ['Domisili', 'Bogor, Jawa Barat']].map(([key, value]) => <div key={key}><dt>{key}</dt><dd>{value}</dd></div>)}</dl></section><section className="v-card v-security-card"><h2>Dokumen pendukung</h2><p>Pilih dokumen untuk mencoba tampilan pengajuan ulang.</p><div className="v-document-list">{[['identity', 'Foto identitas pemilik'], ['business', 'Dokumen legalitas bisnis']].map(([key, label]) => <label className="v-document-upload" key={key}><FileCheck2 size={22} /><span><strong>{label}</strong><small>{files[key] || 'JPG, PNG, atau PDF · maks. 5 MB'}</small></span><Upload size={17} /><input className="v-sr-only" type="file" aria-label={label} accept="image/jpeg,image/png,application/pdf" onChange={event => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 5 * 1024 * 1024 || !['image/jpeg', 'image/png', 'application/pdf'].includes(file.type)) { notify('Pilih JPG, PNG, atau PDF maksimal 5 MB.'); return; } setFiles(current => ({ ...current, [key]: file.name })); }} /></label>)}</div><button className="v-button v-button-secondary" type="button" disabled={!Object.keys(files).length} onClick={() => notify('Dokumen dipilih untuk pratinjau. Tidak ada berkas yang dikirim ke server.')}>Pratinjau pengajuan</button></section></div></>;
}

export default function VendorSettings({ page, settings, onSave, notify }) {
  if (page === 'keamanan') return <Security notify={notify} />;
  if (page === 'kyc') return <Kyc notify={notify} />;
  const type = page === 'profil-bisnis' ? 'business' : 'owner';
  return <><PageHeading title={type === 'business' ? 'Profil bisnis' : 'Profil pemilik'} description={type === 'business' ? 'Lengkapi identitas dan kontak bisnis Anda di Vendoria.' : 'Informasi pemilik yang mengelola workspace vendor.'} /><SettingsForm key={type} type={type} values={settings[type]} onSave={onSave} /></>;
}
